/* Nonmatching */
void daNpcAuction_c::privateCut() {
    static char* cut_name_tbl[] = {
        "MAIN",
        "MES_SET",
    };
    dEvent_manager_c* evm = dComIfGp_getPEvtManager();
    s32 staffId = evm->getMyStaffId(l_npc_staff_id[mNpcNo], NULL, 0);
    if (staffId != -1) {
        mActIdx = evm->getMyActIdx(staffId, cut_name_tbl, 2, 1, 0);
        if ((s8)mActIdx == -1) {
            evm->cutEnd(staffId);
            return;
        }
        if (evm->getIsAddvance(staffId)) {
            switch ((s8)mActIdx) {
            case 0:
                eventMainInit();
                break;
            case 1:
                eventMesSetInit(staffId);
                break;
            }
        }
        int ret;
        switch ((s8)mActIdx) {
        case 0:
            ret = eventMain();
            break;
        case 1:
            ret = eventMesSet();
            break;
        default:
            ret = 1;
            break;
        }
        if ((u8)ret != 0) {
            evm->cutEnd(staffId);
        }
    }
}

