        dNpc_calc_DisXZ_AngY(current.pos, g_dComIfG_gameInfo.play.getPlayerPtr(0)->current.pos, &d, &a);
        if (m73D != 0) {
            dist += 40.0f;
            limitAngle = 0x471C;
            distAngle += 0x71C;
        }
        a -= current.angle.y;
